class WeatherSystem:

    def __init__(self, city) -> None:
        self.temperature = None
        self.weather = None
        self.city = city
        self.weather_list = {}

    def query(self, weather_list, tmp_units='celsius'):
        if self.city not in weather_list:
            raise KeyError(f"City '{self.city}' not found in weather list.")
        if tmp_units not in ['celsius', 'fahrenheit']:
            raise ValueError(f"Invalid temperature units '{tmp_units}'. Must be 'celsius' or 'fahrenheit'.")
        city_weather = weather_list[self.city]
        temperature = city_weather['temperature']
        weather_condition = city_weather['weather']
        if tmp_units == 'fahrenheit':
            temperature = self.celsius_to_fahrenheit(temperature)
        return (temperature, weather_condition)

    def set_city(self, city):
        """Set the city of the weather system.
        :param city: the city to set, str.
        :return: None
        """
        if not isinstance(city, str):
            raise TypeError('City must be a string')
        self.city = city

    def celsius_to_fahrenheit(self):
        """Convert the temperature from Celsius to Fahrenheit.
        :return: the temperature in Fahrenheit, float.
        """
        if self.temperature is None:
            raise ValueError('Temperature is None')
        return self.temperature * 9 / 5 + 32

    def fahrenheit_to_celsius(self):
        """Convert the temperature from Fahrenheit to Celsius.
        :return: the temperature in Celsius, float.
        """
        if self.temperature is None:
            raise ValueError('Temperature is not set.')
        return (self.temperature - 32) / 1.8

